INSERT INTO `app_settings` (`setting_key`, `setting_value`) VALUES ('legacy_definitions','[{\"schema_name\":\"dbo\",\"name\":\"DF__dtpropert__versi__77BFCB91\",\"type_desc\":\"DEFAULT_CONSTRAINT\",\"definition\":null},{\"schema_name\":\"dbo\",\"name\":\"DF_penghasilan_lain1\",\"type_desc\":\"DEFAULT_CONSTRAINT\",\"definition\":null},{\"schema_name\":\"dbo\",\"name\":\"dt_addtosourcecontrol\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_addtosourcecontrol\\r\\n    @vchSourceSafeINI varchar(255) = \'\',\\r\\n    @vchProjectName   varchar(255) =\'\',\\r\\n    @vchComment       varchar(255) =\'\',\\r\\n    @vchLoginName     varchar(255) =\'\',\\r\\n    @vchPassword      varchar(255) =\'\'\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @iStreamObjectId int\\r\\nselect @iStreamObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\ndeclare @vchDatabaseName varchar(255)\\r\\nselect @vchDatabaseName = db_name()\\r\\n\\r\\ndeclare @iReturnValue int\\r\\nselect @iReturnValue = 0\\r\\n\\r\\ndeclare @iPropertyObjectId int\\r\\ndeclare @vchParentId varchar(255)\\r\\n\\r\\ndeclare @iObjectCount int\\r\\nselect @iObjectCount = 0\\r\\n\\r\\n    exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n\\r\\n    \\/* Create Project in SS *\\/\\r\\n    exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                \'AddProjectToSourceSafe\',\\r\\n                                NULL,\\r\\n                                @vchSourceSafeINI,\\r\\n                                @vchProjectName output,\\r\\n                                @@SERVERNAME,\\r\\n                                @vchDatabaseName,\\r\\n                                @vchLoginName,\\r\\n                                @vchPassword,\\r\\n                                @vchComment\\r\\n\\r\\n\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    exec @iReturn = sp_OAGetProperty @iObjectId, \'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    \\/* Set Database Properties *\\/\\r\\n\\r\\n    begin tran SetProperties\\r\\n\\r\\n    \\/* add high level object *\\/\\r\\n\\r\\n    exec @iPropertyObjectId = dbo.dt_adduserobject_vcs \'VCSProjectID\'\\r\\n\\r\\n    select @vchParentId = CONVERT(varchar(255),@iPropertyObjectId)\\r\\n\\r\\n    exec dbo.dt_setpropertybyid @iPropertyObjectId, \'VCSProjectID\', @vchParentId , NULL\\r\\n    exec dbo.dt_setpropertybyid @iPropertyObjectId, \'VCSProject\' , @vchProjectName , NULL\\r\\n    exec dbo.dt_setpropertybyid @iPropertyObjectId, \'VCSSourceSafeINI\' , @vchSourceSafeINI , NULL\\r\\n    exec dbo.dt_setpropertybyid @iPropertyObjectId, \'VCSSQLServer\', @@SERVERNAME, NULL\\r\\n    exec dbo.dt_setpropertybyid @iPropertyObjectId, \'VCSSQLDatabase\', @vchDatabaseName, NULL\\r\\n\\r\\n    if @@error <> 0 GOTO E_General_Error\\r\\n\\r\\n    commit tran SetProperties\\r\\n\\r\\n    declare cursorProcNames cursor for\\r\\n        select convert(varchar(255), name) from sysobjects where type = \'P\' and name not like \'dt_%\'\\r\\n    open cursorProcNames\\r\\n\\r\\n    while 1 = 1\\r\\n    begin\\r\\n        declare @vchProcName varchar(255)\\r\\n        fetch next from cursorProcNames into @vchProcName\\r\\n        if @@fetch_status <> 0\\r\\n            break\\r\\n\\r\\n        select colid, text into #ProcLines\\r\\n        from syscomments\\r\\n        where id = object_id(@vchProcName)\\r\\n        order by colid\\r\\n\\r\\n        declare @iCurProcLine int\\r\\n        declare @iProcLines int\\r\\n        select @iCurProcLine = 1\\r\\n        select @iProcLines = (select count(*) from #ProcLines)\\r\\n        while @iCurProcLine <= @iProcLines\\r\\n        begin\\r\\n            declare @pos int\\r\\n            select @pos = 1\\r\\n            declare @iCurLineSize int\\r\\n            select @iCurLineSize = len((select text from #ProcLines where colid = @iCurProcLine))\\r\\n            while @pos <= @iCurLineSize\\r\\n            begin\\r\\n                declare @vchProcLinePiece varchar(255)\\r\\n                select @vchProcLinePiece = convert(varchar(255),\\r\\n                    substring((select text from #ProcLines where colid = @iCurProcLine),\\r\\n                              @pos, 255 ))\\r\\n                exec @iReturn = sp_OAMethod @iStreamObjectId, \'AddStream\', @iReturnValue OUT, @vchProcLinePiece\\r\\n                if @iReturn <> 0 GOTO E_OAError\\r\\n                select @pos = @pos + 255\\r\\n            end\\r\\n            select @iCurProcLine = @iCurProcLine + 1\\r\\n        end\\r\\n        drop table #ProcLines\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    \'CheckIn_StoredProcedure\',\\r\\n                                    NULL,\\r\\n                                    @sProjectName = @vchProjectName,\\r\\n                                    @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                    @sServerName = @@SERVERNAME,\\r\\n                                    @sDatabaseName = @vchDatabaseName,\\r\\n                                    @sObjectName = @vchProcName,\\r\\n                                    @sComment = @vchComment,\\r\\n                                    @sLoginName = @vchLoginName,\\r\\n                                    @sPassword = @vchPassword,\\r\\n                                    @iVCSFlags = 0,\\r\\n                                    @iActionFlag = 0,\\r\\n                                    @sStream = \'\'\\r\\n\\r\\n        if @iReturn = 0 select @iObjectCount = @iObjectCount + 1\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n\\tclose cursorProcNames\\r\\n\\tdeallocate cursorProcNames\\r\\n    select @vchProjectName\\r\\n    select @iObjectCount\\r\\n    return\\r\\n\\r\\nE_General_Error:\\r\\n    \\/* this is an all or nothing.  No specific error messages *\\/\\r\\n    goto CleanUp\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_addtosourcecontrol_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_addtosourcecontrol_u\\r\\n    @vchSourceSafeINI nvarchar(255) = \'\',\\r\\n    @vchProjectName   nvarchar(255) =\'\',\\r\\n    @vchComment       nvarchar(255) =\'\',\\r\\n    @vchLoginName     nvarchar(255) =\'\',\\r\\n    @vchPassword      nvarchar(255) =\'\'\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @iStreamObjectId int\\r\\nselect @iStreamObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID nvarchar(100)\\r\\nselect @VSSGUID = N\'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\ndeclare @vchDatabaseName varchar(255)\\r\\nselect @vchDatabaseName = db_name()\\r\\n\\r\\ndeclare @iReturnValue int\\r\\nselect @iReturnValue = 0\\r\\n\\r\\ndeclare @iPropertyObjectId int\\r\\ndeclare @vchParentId nvarchar(255)\\r\\n\\r\\ndeclare @iObjectCount int\\r\\nselect @iObjectCount = 0\\r\\n\\r\\n    exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n\\r\\n    \\/* Create Project in SS *\\/\\r\\n    exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                \'AddProjectToSourceSafe\',\\r\\n                                NULL,\\r\\n                                @vchSourceSafeINI,\\r\\n                                @vchProjectName output,\\r\\n                                @@SERVERNAME,\\r\\n                                @vchDatabaseName,\\r\\n                                @vchLoginName,\\r\\n                                @vchPassword,\\r\\n                                @vchComment\\r\\n\\r\\n\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    exec @iReturn = sp_OAGetProperty @iObjectId, N\'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    \\/* Set Database Properties *\\/\\r\\n\\r\\n    begin tran SetProperties\\r\\n\\r\\n    \\/* add high level object *\\/\\r\\n\\r\\n    exec @iPropertyObjectId = dbo.dt_adduserobject_vcs \'VCSProjectID\'\\r\\n\\r\\n    select @vchParentId = CONVERT(nvarchar(255),@iPropertyObjectId)\\r\\n\\r\\n    exec dbo.dt_setpropertybyid_u @iPropertyObjectId, \'VCSProjectID\', @vchParentId , NULL\\r\\n    exec dbo.dt_setpropertybyid_u @iPropertyObjectId, \'VCSProject\' , @vchProjectName , NULL\\r\\n    exec dbo.dt_setpropertybyid_u @iPropertyObjectId, \'VCSSourceSafeINI\' , @vchSourceSafeINI , NULL\\r\\n    exec dbo.dt_setpropertybyid_u @iPropertyObjectId, \'VCSSQLServer\', @@SERVERNAME, NULL\\r\\n    exec dbo.dt_setpropertybyid_u @iPropertyObjectId, \'VCSSQLDatabase\', @vchDatabaseName, NULL\\r\\n\\r\\n    if @@error <> 0 GOTO E_General_Error\\r\\n\\r\\n    commit tran SetProperties\\r\\n\\r\\n    declare cursorProcNames cursor for\\r\\n        select convert(nvarchar(255), name) from sysobjects where type = N\'P\' and name not like N\'dt_%\'\\r\\n    open cursorProcNames\\r\\n\\r\\n    while 1 = 1\\r\\n    begin\\r\\n        declare @vchProcName nvarchar(255)\\r\\n        fetch next from cursorProcNames into @vchProcName\\r\\n        if @@fetch_status <> 0\\r\\n            break\\r\\n\\r\\n        select colid, text into #ProcLines\\r\\n        from syscomments\\r\\n        where id = object_id(@vchProcName)\\r\\n        order by colid\\r\\n\\r\\n        declare @iCurProcLine int\\r\\n        declare @iProcLines int\\r\\n        select @iCurProcLine = 1\\r\\n        select @iProcLines = (select count(*) from #ProcLines)\\r\\n        while @iCurProcLine <= @iProcLines\\r\\n        begin\\r\\n            declare @pos int\\r\\n            select @pos = 1\\r\\n            declare @iCurLineSize int\\r\\n            select @iCurLineSize = len((select text from #ProcLines where colid = @iCurProcLine))\\r\\n            while @pos <= @iCurLineSize\\r\\n            begin\\r\\n                declare @vchProcLinePiece nvarchar(255)\\r\\n                select @vchProcLinePiece = convert(nvarchar(255),\\r\\n                    substring((select text from #ProcLines where colid = @iCurProcLine),\\r\\n                              @pos, 255 ))\\r\\n                exec @iReturn = sp_OAMethod @iStreamObjectId, N\'AddStream\', @iReturnValue OUT, @vchProcLinePiece\\r\\n                if @iReturn <> 0 GOTO E_OAError\\r\\n                select @pos = @pos + 255\\r\\n            end\\r\\n            select @iCurProcLine = @iCurProcLine + 1\\r\\n        end\\r\\n        drop table #ProcLines\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    \'CheckIn_StoredProcedure\',\\r\\n                                    NULL,\\r\\n                                    @sProjectName = @vchProjectName,\\r\\n                                    @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                    @sServerName = @@SERVERNAME,\\r\\n                                    @sDatabaseName = @vchDatabaseName,\\r\\n                                    @sObjectName = @vchProcName,\\r\\n                                    @sComment = @vchComment,\\r\\n                                    @sLoginName = @vchLoginName,\\r\\n                                    @sPassword = @vchPassword,\\r\\n                                    @iVCSFlags = 0,\\r\\n                                    @iActionFlag = 0,\\r\\n                                    @sStream = \'\'\\r\\n\\r\\n        if @iReturn = 0 select @iObjectCount = @iObjectCount + 1\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n\\tclose cursorProcNames\\r\\n\\tdeallocate cursorProcNames\\r\\n    select @vchProjectName\\r\\n    select @iObjectCount\\r\\n    return\\r\\n\\r\\nE_General_Error:\\r\\n    \\/* this is an all or nothing.  No specific error messages *\\/\\r\\n    goto CleanUp\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror_u @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_adduserobject\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tAdd an object to the dtproperties table\\r\\n*\\/\\r\\ncreate procedure dbo.dt_adduserobject\\r\\nas\\r\\n\\tset nocount on\\r\\n\\t\\/*\\r\\n\\t** Create the user object if it does not exist already\\r\\n\\t*\\/\\r\\n\\tbegin transaction\\r\\n\\t\\tinsert dbo.dtproperties (property) VALUES (\'DtgSchemaOBJECT\')\\r\\n\\t\\tupdate dbo.dtproperties set objectid=@@identity \\r\\n\\t\\t\\twhere id=@@identity and property=\'DtgSchemaOBJECT\'\\r\\n\\tcommit\\r\\n\\treturn @@identity\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_adduserobject_vcs\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create procedure dbo.dt_adduserobject_vcs\\r\\n    @vchProperty varchar(64)\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\n    \\/*\\r\\n    ** Create the user object if it does not exist already\\r\\n    *\\/\\r\\n    begin transaction\\r\\n        select @iReturn = objectid from dbo.dtproperties where property = @vchProperty\\r\\n        if @iReturn IS NULL\\r\\n        begin\\r\\n            insert dbo.dtproperties (property) VALUES (@vchProperty)\\r\\n            update dbo.dtproperties set objectid=@@identity\\r\\n                    where id=@@identity and property=@vchProperty\\r\\n            select @iReturn = @@identity\\r\\n        end\\r\\n    commit\\r\\n    return @iReturn\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_checkinobject\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_checkinobject\\r\\n    @chObjectType  char(4),\\r\\n    @vchObjectName varchar(255),\\r\\n    @vchComment    varchar(255)=\'\',\\r\\n    @vchLoginName  varchar(255),\\r\\n    @vchPassword   varchar(255)=\'\',\\r\\n    @iVCSFlags     int = 0,\\r\\n    @iActionFlag   int = 0,   \\/* 0 => AddFile, 1 => CheckIn *\\/\\r\\n    @txStream1     Text = \'\', \\/* There is a bug that if items are NULL they do not pass to OLE servers *\\/\\r\\n    @txStream2     Text = \'\',\\r\\n    @txStream3     Text = \'\'\\r\\n\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n\\r\\ndeclare @iPropertyObjectId int\\r\\nselect @iPropertyObjectId  = 0\\r\\n\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   varchar(255)\\r\\n    declare @vchSourceSafeINI varchar(255)\\r\\n    declare @vchServerName    varchar(255)\\r\\n    declare @vchDatabaseName  varchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if @chObjectType = \'PROC\'\\r\\n    begin\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            \\/* Procedure Can have up to three streams\\r\\n            Drop Stream, Create Stream, GRANT stream *\\/\\r\\n\\r\\n            begin tran compile_all\\r\\n\\r\\n            \\/* try to compile the streams *\\/\\r\\n            exec (@txStream1)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n\\r\\n            exec (@txStream2)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n\\r\\n            exec (@txStream3)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n        end\\r\\n\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                        \'CheckIn_StoredProcedure\',\\r\\n                                        NULL,\\r\\n                                        @sProjectName = @vchProjectName,\\r\\n                                        @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                        @sServerName = @vchServerName,\\r\\n                                        @sDatabaseName = @vchDatabaseName,\\r\\n                                        @sObjectName = @vchObjectName,\\r\\n                                        @sComment = @vchComment,\\r\\n                                        @sLoginName = @vchLoginName,\\r\\n                                        @sPassword = @vchPassword,\\r\\n                                        @iVCSFlags = @iVCSFlags,\\r\\n                                        @iActionFlag = @iActionFlag,\\r\\n                                        @sStream = @txStream2\\r\\n        end\\r\\n        else\\r\\n        begin\\r\\n            declare @iStreamObjectId int\\r\\n            declare @iReturnValue int\\r\\n\\r\\n            exec @iReturn = sp_OAGetProperty @iObjectId, \'GetStreamObject\', @iStreamObjectId OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            select colid, text into #ProcLines\\r\\n            from syscomments\\r\\n            where id = object_id(@vchObjectName)\\r\\n            order by colid\\r\\n\\r\\n            declare @iCurProcLine int\\r\\n            declare @iProcLines int\\r\\n            select @iCurProcLine = 1\\r\\n            select @iProcLines = (select count(*) from #ProcLines)\\r\\n            while @iCurProcLine <= @iProcLines\\r\\n            begin\\r\\n                declare @pos int\\r\\n                select @pos = 1\\r\\n                declare @iCurLineSize int\\r\\n                select @iCurLineSize = len((select text from #ProcLines where colid = @iCurProcLine))\\r\\n                while @pos <= @iCurLineSize\\r\\n                begin\\r\\n                    declare @vchProcLinePiece varchar(255)\\r\\n                    select @vchProcLinePiece = convert(varchar(255),\\r\\n                        substring((select text from #ProcLines where colid = @iCurProcLine),\\r\\n                                  @pos, 255 ))\\r\\n                    exec @iReturn = sp_OAMethod @iStreamObjectId, \'AddStream\', @iReturnValue OUT, @vchProcLinePiece\\r\\n                    if @iReturn <> 0 GOTO E_OAError\\r\\n                    select @pos = @pos + 255\\r\\n                end\\r\\n                select @iCurProcLine = @iCurProcLine + 1\\r\\n            end\\r\\n            drop table #ProcLines\\r\\n\\r\\n            exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                        \'CheckIn_StoredProcedure\',\\r\\n                                        NULL,\\r\\n                                        @sProjectName = @vchProjectName,\\r\\n                                        @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                        @sServerName = @vchServerName,\\r\\n                                        @sDatabaseName = @vchDatabaseName,\\r\\n                                        @sObjectName = @vchObjectName,\\r\\n                                        @sComment = @vchComment,\\r\\n                                        @sLoginName = @vchLoginName,\\r\\n                                        @sPassword = @vchPassword,\\r\\n                                        @iVCSFlags = @iVCSFlags,\\r\\n                                        @iActionFlag = @iActionFlag,\\r\\n                                        @sStream = \'\'\\r\\n        end\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            commit tran compile_all\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n        end\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_Compile_Fail:\\r\\n    declare @lerror int\\r\\n    select @lerror = @@error\\r\\n    rollback tran compile_all\\r\\n    RAISERROR (@lerror,16,-1)\\r\\n    goto CleanUp\\r\\n\\r\\nE_OAError:\\r\\n    if @iActionFlag = 1 rollback tran compile_all\\r\\n    exec dbo.dt_displayoaerror @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_checkinobject_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_checkinobject_u\\r\\n    @chObjectType  char(4),\\r\\n    @vchObjectName nvarchar(255),\\r\\n    @vchComment    nvarchar(255)=\'\',\\r\\n    @vchLoginName  nvarchar(255),\\r\\n    @vchPassword   nvarchar(255)=\'\',\\r\\n    @iVCSFlags     int = 0,\\r\\n    @iActionFlag   int = 0,   \\/* 0 => AddFile, 1 => CheckIn *\\/\\r\\n    @txStream1     Text = \'\', \\/* There is a bug that if items are NULL they do not pass to OLE servers *\\/\\r\\n    @txStream2     Text = \'\',\\r\\n    @txStream3     Text = \'\'\\r\\n\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID nvarchar(100)\\r\\nselect @VSSGUID = N\'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n\\r\\ndeclare @iPropertyObjectId int\\r\\nselect @iPropertyObjectId  = 0\\r\\n\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   nvarchar(255)\\r\\n    declare @vchSourceSafeINI nvarchar(255)\\r\\n    declare @vchServerName    nvarchar(255)\\r\\n    declare @vchDatabaseName  nvarchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if @chObjectType = \'PROC\'\\r\\n    begin\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            \\/* Procedure Can have up to three streams\\r\\n            Drop Stream, Create Stream, GRANT stream *\\/\\r\\n\\r\\n            begin tran compile_all\\r\\n\\r\\n            \\/* try to compile the streams *\\/\\r\\n            exec (@txStream1)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n\\r\\n            exec (@txStream2)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n\\r\\n            exec (@txStream3)\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n        end\\r\\n\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                        N\'CheckIn_StoredProcedure\',\\r\\n                                        NULL,\\r\\n                                        @sProjectName = @vchProjectName,\\r\\n                                        @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                        @sServerName = @vchServerName,\\r\\n                                        @sDatabaseName = @vchDatabaseName,\\r\\n                                        @sObjectName = @vchObjectName,\\r\\n                                        @sComment = @vchComment,\\r\\n                                        @sLoginName = @vchLoginName,\\r\\n                                        @sPassword = @vchPassword,\\r\\n                                        @iVCSFlags = @iVCSFlags,\\r\\n                                        @iActionFlag = @iActionFlag,\\r\\n                                        @sStream = @txStream2\\r\\n        end\\r\\n        else\\r\\n        begin\\r\\n            declare @iStreamObjectId int\\r\\n            declare @iReturnValue int\\r\\n\\r\\n            exec @iReturn = sp_OAGetProperty @iObjectId, N\'GetStreamObject\', @iStreamObjectId OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            select colid, text into #ProcLines\\r\\n            from syscomments\\r\\n            where id = object_id(@vchObjectName)\\r\\n            order by colid\\r\\n\\r\\n            declare @iCurProcLine int\\r\\n            declare @iProcLines int\\r\\n            select @iCurProcLine = 1\\r\\n            select @iProcLines = (select count(*) from #ProcLines)\\r\\n            while @iCurProcLine <= @iProcLines\\r\\n            begin\\r\\n                declare @pos int\\r\\n                select @pos = 1\\r\\n                declare @iCurLineSize int\\r\\n                select @iCurLineSize = len((select text from #ProcLines where colid = @iCurProcLine))\\r\\n                while @pos <= @iCurLineSize\\r\\n                begin\\r\\n                    declare @vchProcLinePiece nvarchar(255)\\r\\n                    select @vchProcLinePiece = convert(nvarchar(255),\\r\\n                        substring((select text from #ProcLines where colid = @iCurProcLine),\\r\\n                                  @pos, 255 ))\\r\\n                    exec @iReturn = sp_OAMethod @iStreamObjectId, N\'AddStream\', @iReturnValue OUT, @vchProcLinePiece\\r\\n                    if @iReturn <> 0 GOTO E_OAError\\r\\n                    select @pos = @pos + 255\\r\\n                end\\r\\n                select @iCurProcLine = @iCurProcLine + 1\\r\\n            end\\r\\n            drop table #ProcLines\\r\\n\\r\\n            exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                        N\'CheckIn_StoredProcedure\',\\r\\n                                        NULL,\\r\\n                                        @sProjectName = @vchProjectName,\\r\\n                                        @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                        @sServerName = @vchServerName,\\r\\n                                        @sDatabaseName = @vchDatabaseName,\\r\\n                                        @sObjectName = @vchObjectName,\\r\\n                                        @sComment = @vchComment,\\r\\n                                        @sLoginName = @vchLoginName,\\r\\n                                        @sPassword = @vchPassword,\\r\\n                                        @iVCSFlags = @iVCSFlags,\\r\\n                                        @iActionFlag = @iActionFlag,\\r\\n                                        @sStream = \'\'\\r\\n        end\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        if @iActionFlag = 1\\r\\n        begin\\r\\n            commit tran compile_all\\r\\n            if @@error <> 0 GOTO E_Compile_Fail\\r\\n        end\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_Compile_Fail:\\r\\n    declare @lerror int\\r\\n    select @lerror = @@error\\r\\n    rollback tran compile_all\\r\\n    RAISERROR (@lerror,16,-1)\\r\\n    goto CleanUp\\r\\n\\r\\nE_OAError:\\r\\n    if @iActionFlag = 1 rollback tran compile_all\\r\\n    exec dbo.dt_displayoaerror_u @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_checkoutobject\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_checkoutobject\\r\\n    @chObjectType  char(4),\\r\\n    @vchObjectName varchar(255),\\r\\n    @vchComment    varchar(255),\\r\\n    @vchLoginName  varchar(255),\\r\\n    @vchPassword   varchar(255),\\r\\n    @iVCSFlags     int = 0,\\r\\n    @iActionFlag   int = 0\\/* 0 => Checkout, 1 => GetLatest, 2 => UndoCheckOut *\\/\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId =0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\ndeclare @iReturnValue int\\r\\nselect @iReturnValue = 0\\r\\n\\r\\ndeclare @vchTempText varchar(255)\\r\\n\\r\\n\\/* this is for our strings *\\/\\r\\ndeclare @iStreamObjectId int\\r\\nselect @iStreamObjectId = 0\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   varchar(255)\\r\\n    declare @vchSourceSafeINI varchar(255)\\r\\n    declare @vchServerName    varchar(255)\\r\\n    declare @vchDatabaseName  varchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if @chObjectType = \'PROC\'\\r\\n    begin\\r\\n        \\/* Procedure Can have up to three streams\\r\\n           Drop Stream, Create Stream, GRANT stream *\\/\\r\\n\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    \'CheckOut_StoredProcedure\',\\r\\n                                    NULL,\\r\\n                                    @sProjectName = @vchProjectName,\\r\\n                                    @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                    @sObjectName = @vchObjectName,\\r\\n                                    @sServerName = @vchServerName,\\r\\n                                    @sDatabaseName = @vchDatabaseName,\\r\\n                                    @sComment = @vchComment,\\r\\n                                    @sLoginName = @vchLoginName,\\r\\n                                    @sPassword = @vchPassword,\\r\\n                                    @iVCSFlags = @iVCSFlags,\\r\\n                                    @iActionFlag = @iActionFlag\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n\\r\\n        exec @iReturn = sp_OAGetProperty @iObjectId, \'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        create table #commenttext (id int identity, sourcecode varchar(255))\\r\\n\\r\\n\\r\\n        select @vchTempText = \'STUB\'\\r\\n        while @vchTempText IS NOT NULL\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iStreamObjectId, \'GetStream\', @iReturnValue OUT, @vchTempText OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            if (@vchTempText IS NOT NULL) insert into #commenttext (sourcecode) select @vchTempText\\r\\n        end\\r\\n\\r\\n        select \'VCS\'=sourcecode from #commenttext order by id\\r\\n        select \'SQL\'=text from syscomments where id = object_id(@vchObjectName) order by colid\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror @iObjectId, @iReturn\\r\\n    GOTO CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_checkoutobject_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_checkoutobject_u\\r\\n    @chObjectType  char(4),\\r\\n    @vchObjectName nvarchar(255),\\r\\n    @vchComment    nvarchar(255),\\r\\n    @vchLoginName  nvarchar(255),\\r\\n    @vchPassword   nvarchar(255),\\r\\n    @iVCSFlags     int = 0,\\r\\n    @iActionFlag   int = 0\\/* 0 => Checkout, 1 => GetLatest, 2 => UndoCheckOut *\\/\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId =0\\r\\n\\r\\ndeclare @VSSGUID nvarchar(100)\\r\\nselect @VSSGUID = N\'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\ndeclare @iReturnValue int\\r\\nselect @iReturnValue = 0\\r\\n\\r\\ndeclare @vchTempText nvarchar(255)\\r\\n\\r\\n\\/* this is for our strings *\\/\\r\\ndeclare @iStreamObjectId int\\r\\nselect @iStreamObjectId = 0\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   nvarchar(255)\\r\\n    declare @vchSourceSafeINI nvarchar(255)\\r\\n    declare @vchServerName    nvarchar(255)\\r\\n    declare @vchDatabaseName  nvarchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if @chObjectType = \'PROC\'\\r\\n    begin\\r\\n        \\/* Procedure Can have up to three streams\\r\\n           Drop Stream, Create Stream, GRANT stream *\\/\\r\\n\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    N\'CheckOut_StoredProcedure\',\\r\\n                                    NULL,\\r\\n                                    @sProjectName = @vchProjectName,\\r\\n                                    @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                    @sObjectName = @vchObjectName,\\r\\n                                    @sServerName = @vchServerName,\\r\\n                                    @sDatabaseName = @vchDatabaseName,\\r\\n                                    @sComment = @vchComment,\\r\\n                                    @sLoginName = @vchLoginName,\\r\\n                                    @sPassword = @vchPassword,\\r\\n                                    @iVCSFlags = @iVCSFlags,\\r\\n                                    @iActionFlag = @iActionFlag\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n\\r\\n        exec @iReturn = sp_OAGetProperty @iObjectId, N\'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        create table #commenttext (id int identity, sourcecode nvarchar(255))\\r\\n\\r\\n\\r\\n        select @vchTempText = N\'STUB\'\\r\\n        while @vchTempText IS NOT NULL\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iStreamObjectId, N\'GetStream\', @iReturnValue OUT, @vchTempText OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            if (@vchTempText IS NOT NULL) insert into #commenttext (sourcecode) select @vchTempText\\r\\n        end\\r\\n\\r\\n        select N\'VCS\'=sourcecode from #commenttext order by id\\r\\n        select N\'SQL\'=text from syscomments where id = object_id(@vchObjectName) order by colid\\r\\n\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror_u @iObjectId, @iReturn\\r\\n    GOTO CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_displayoaerror\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"CREATE PROCEDURE dbo.dt_displayoaerror\\r\\n    @iObject int,\\r\\n    @iresult int\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @vchOutput      varchar(255)\\r\\ndeclare @hr             int\\r\\ndeclare @vchSource      varchar(255)\\r\\ndeclare @vchDescription varchar(255)\\r\\n\\r\\n    exec @hr = sp_OAGetErrorInfo @iObject, @vchSource OUT, @vchDescription OUT\\r\\n\\r\\n    select @vchOutput = @vchSource + \': \' + @vchDescription\\r\\n    raiserror (@vchOutput,16,-1)\\r\\n\\r\\n    return\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_displayoaerror_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"CREATE PROCEDURE dbo.dt_displayoaerror_u\\r\\n    @iObject int,\\r\\n    @iresult int\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @vchOutput      nvarchar(255)\\r\\ndeclare @hr             int\\r\\ndeclare @vchSource      nvarchar(255)\\r\\ndeclare @vchDescription nvarchar(255)\\r\\n\\r\\n    exec @hr = sp_OAGetErrorInfo @iObject, @vchSource OUT, @vchDescription OUT\\r\\n\\r\\n    select @vchOutput = @vchSource + \': \' + @vchDescription\\r\\n    raiserror (@vchOutput,16,-1)\\r\\n\\r\\n    return\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_droppropertiesbyid\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tDrop one or all the associated properties of an object or an attribute \\r\\n**\\r\\n**\\tdt_dropproperties objid, null or \'\' -- drop all properties of the object itself\\r\\n**\\tdt_dropproperties objid, property -- drop the property\\r\\n*\\/\\r\\ncreate procedure dbo.dt_droppropertiesbyid\\r\\n\\t@id int,\\r\\n\\t@property varchar(64)\\r\\nas\\r\\n\\tset nocount on\\r\\n\\r\\n\\tif (@property is null) or (@property = \'\')\\r\\n\\t\\tdelete from dbo.dtproperties where objectid=@id\\r\\n\\telse\\r\\n\\t\\tdelete from dbo.dtproperties \\r\\n\\t\\t\\twhere objectid=@id and property=@property\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_dropuserobjectbyid\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tDrop an object from the dbo.dtproperties table\\r\\n*\\/\\r\\ncreate procedure dbo.dt_dropuserobjectbyid\\r\\n\\t@id int\\r\\nas\\r\\n\\tset nocount on\\r\\n\\tdelete from dbo.dtproperties where objectid=@id\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_generateansiname\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/* \\r\\n**\\tGenerate an ansi name that is unique in the dtproperties.value column \\r\\n*\\/ \\r\\ncreate procedure dbo.dt_generateansiname(@name varchar(255) output) \\r\\nas \\r\\n\\tdeclare @prologue varchar(20) \\r\\n\\tdeclare @indexstring varchar(20) \\r\\n\\tdeclare @index integer \\r\\n \\r\\n\\tset @prologue = \'MSDT-A-\' \\r\\n\\tset @index = 1 \\r\\n \\r\\n\\twhile 1 = 1 \\r\\n\\tbegin \\r\\n\\t\\tset @indexstring = cast(@index as varchar(20)) \\r\\n\\t\\tset @name = @prologue + @indexstring \\r\\n\\t\\tif not exists (select value from dtproperties where value = @name) \\r\\n\\t\\t\\tbreak \\r\\n\\t\\t \\r\\n\\t\\tset @index = @index + 1 \\r\\n \\r\\n\\t\\tif (@index = 10000) \\r\\n\\t\\t\\tgoto TooMany \\r\\n\\tend \\r\\n \\r\\nLeave: \\r\\n \\r\\n\\treturn \\r\\n \\r\\nTooMany: \\r\\n \\r\\n\\tset @name = \'DIAGRAM\' \\r\\n\\tgoto Leave \\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getobjwithprop\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tRetrieve the owner object(s) of a given property\\r\\n*\\/\\r\\ncreate procedure dbo.dt_getobjwithprop\\r\\n\\t@property varchar(30),\\r\\n\\t@value varchar(255)\\r\\nas\\r\\n\\tset nocount on\\r\\n\\r\\n\\tif (@property is null) or (@property = \'\')\\r\\n\\tbegin\\r\\n\\t\\traiserror(\'Must specify a property name.\',-1,-1)\\r\\n\\t\\treturn (1)\\r\\n\\tend\\r\\n\\r\\n\\tif (@value is null)\\r\\n\\t\\tselect objectid id from dbo.dtproperties\\r\\n\\t\\t\\twhere property=@property\\r\\n\\r\\n\\telse\\r\\n\\t\\tselect objectid id from dbo.dtproperties\\r\\n\\t\\t\\twhere property=@property and value=@value\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getobjwithprop_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tRetrieve the owner object(s) of a given property\\r\\n*\\/\\r\\ncreate procedure dbo.dt_getobjwithprop_u\\r\\n\\t@property varchar(30),\\r\\n\\t@uvalue nvarchar(255)\\r\\nas\\r\\n\\tset nocount on\\r\\n\\r\\n\\tif (@property is null) or (@property = \'\')\\r\\n\\tbegin\\r\\n\\t\\traiserror(\'Must specify a property name.\',-1,-1)\\r\\n\\t\\treturn (1)\\r\\n\\tend\\r\\n\\r\\n\\tif (@uvalue is null)\\r\\n\\t\\tselect objectid id from dbo.dtproperties\\r\\n\\t\\t\\twhere property=@property\\r\\n\\r\\n\\telse\\r\\n\\t\\tselect objectid id from dbo.dtproperties\\r\\n\\t\\t\\twhere property=@property and uvalue=@uvalue\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getpropertiesbyid\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tRetrieve properties by id\'s\\r\\n**\\r\\n**\\tdt_getproperties objid, null or \'\' -- retrieve all properties of the object itself\\r\\n**\\tdt_getproperties objid, property -- retrieve the property specified\\r\\n*\\/\\r\\ncreate procedure dbo.dt_getpropertiesbyid\\r\\n\\t@id int,\\r\\n\\t@property varchar(64)\\r\\nas\\r\\n\\tset nocount on\\r\\n\\r\\n\\tif (@property is null) or (@property = \'\')\\r\\n\\t\\tselect property, version, value, lvalue\\r\\n\\t\\t\\tfrom dbo.dtproperties\\r\\n\\t\\t\\twhere  @id=objectid\\r\\n\\telse\\r\\n\\t\\tselect property, version, value, lvalue\\r\\n\\t\\t\\tfrom dbo.dtproperties\\r\\n\\t\\t\\twhere  @id=objectid and @property=property\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getpropertiesbyid_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tRetrieve properties by id\'s\\r\\n**\\r\\n**\\tdt_getproperties objid, null or \'\' -- retrieve all properties of the object itself\\r\\n**\\tdt_getproperties objid, property -- retrieve the property specified\\r\\n*\\/\\r\\ncreate procedure dbo.dt_getpropertiesbyid_u\\r\\n\\t@id int,\\r\\n\\t@property varchar(64)\\r\\nas\\r\\n\\tset nocount on\\r\\n\\r\\n\\tif (@property is null) or (@property = \'\')\\r\\n\\t\\tselect property, version, uvalue, lvalue\\r\\n\\t\\t\\tfrom dbo.dtproperties\\r\\n\\t\\t\\twhere  @id=objectid\\r\\n\\telse\\r\\n\\t\\tselect property, version, uvalue, lvalue\\r\\n\\t\\t\\tfrom dbo.dtproperties\\r\\n\\t\\t\\twhere  @id=objectid and @property=property\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getpropertiesbyid_vcs\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create procedure dbo.dt_getpropertiesbyid_vcs\\r\\n    @id       int,\\r\\n    @property varchar(64),\\r\\n    @value    varchar(255) = NULL OUT\\r\\n\\r\\nas\\r\\n\\r\\n    set nocount on\\r\\n\\r\\n    select @value = (\\r\\n        select value\\r\\n                from dbo.dtproperties\\r\\n                where @id=objectid and @property=property\\r\\n                )\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_getpropertiesbyid_vcs_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create procedure dbo.dt_getpropertiesbyid_vcs_u\\r\\n    @id       int,\\r\\n    @property varchar(64),\\r\\n    @value    nvarchar(255) = NULL OUT\\r\\n\\r\\nas\\r\\n\\r\\n    set nocount on\\r\\n\\r\\n    select @value = (\\r\\n        select uvalue\\r\\n                from dbo.dtproperties\\r\\n                where @id=objectid and @property=property\\r\\n                )\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_isundersourcecontrol\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_isundersourcecontrol\\r\\n    @vchLoginName varchar(255) = \'\',\\r\\n    @vchPassword  varchar(255) = \'\',\\r\\n    @iWhoToo      int = 0 \\/* 0 => Just check project; 1 => get list of objs *\\/\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\ndeclare @iReturnValue int\\r\\nselect @iReturnValue = 0\\r\\n\\r\\ndeclare @iStreamObjectId int\\r\\nselect @iStreamObjectId   = 0\\r\\n\\r\\ndeclare @vchTempText varchar(255)\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   varchar(255)\\r\\n    declare @vchSourceSafeINI varchar(255)\\r\\n    declare @vchServerName    varchar(255)\\r\\n    declare @vchDatabaseName  varchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if (@vchProjectName IS NULL) or (@vchSourceSafeINI  IS NULL) or (@vchServerName IS NULL) or (@vchDatabaseName IS NULL)\\r\\n    begin\\r\\n        RAISERROR(\'Not Under Source Control\',16,-1)\\r\\n        return\\r\\n    end\\r\\n\\r\\n    if @iWhoToo = 1\\r\\n    begin\\r\\n\\r\\n        \\/* Get List of Procs in the project *\\/\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    \'GetListOfObjects\',\\r\\n                                    NULL,\\r\\n                                    @vchProjectName,\\r\\n                                    @vchSourceSafeINI,\\r\\n                                    @vchServerName,\\r\\n                                    @vchDatabaseName,\\r\\n                                    @vchLoginName,\\r\\n                                    @vchPassword\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAGetProperty @iObjectId, \'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        create table #ObjectList (id int identity, vchObjectlist varchar(255))\\r\\n\\r\\n        select @vchTempText = \'STUB\'\\r\\n        while @vchTempText IS NOT NULL\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iStreamObjectId, \'GetStream\', @iReturnValue OUT, @vchTempText OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            if (@vchTempText IS NOT NULL) insert into #ObjectList (vchObjectlist ) select @vchTempText\\r\\n        end\\r\\n\\r\\n        select vchObjectlist from #ObjectList order by id\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_isundersourcecontrol_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_isundersourcecontrol_u\\r\\n    @vchLoginName nvarchar(255) = \'\',\\r\\n    @vchPassword  nvarchar(255) = \'\',\\r\\n    @iWhoToo      int = 0 \\/* 0 => Just check project; 1 => get list of objs *\\/\\r\\n\\r\\nas\\r\\n\\r\\n\\tset nocount on\\r\\n\\r\\n\\tdeclare @iReturn int\\r\\n\\tdeclare @iObjectId int\\r\\n\\tselect @iObjectId = 0\\r\\n\\r\\n\\tdeclare @VSSGUID nvarchar(100)\\r\\n\\tselect @VSSGUID = N\'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n\\tdeclare @iReturnValue int\\r\\n\\tselect @iReturnValue = 0\\r\\n\\r\\n\\tdeclare @iStreamObjectId int\\r\\n\\tselect @iStreamObjectId   = 0\\r\\n\\r\\n\\tdeclare @vchTempText nvarchar(255)\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchProjectName   nvarchar(255)\\r\\n    declare @vchSourceSafeINI nvarchar(255)\\r\\n    declare @vchServerName    nvarchar(255)\\r\\n    declare @vchDatabaseName  nvarchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSProject\',       @vchProjectName   OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLServer\',     @vchServerName    OUT\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSQLDatabase\',   @vchDatabaseName  OUT\\r\\n\\r\\n    if (@vchProjectName IS NULL) or (@vchSourceSafeINI  IS NULL) or (@vchServerName IS NULL) or (@vchDatabaseName IS NULL)\\r\\n    begin\\r\\n        RAISERROR(N\'Not Under Source Control\',16,-1)\\r\\n        return\\r\\n    end\\r\\n\\r\\n    if @iWhoToo = 1\\r\\n    begin\\r\\n\\r\\n        \\/* Get List of Procs in the project *\\/\\r\\n        exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                    N\'GetListOfObjects\',\\r\\n                                    NULL,\\r\\n                                    @vchProjectName,\\r\\n                                    @vchSourceSafeINI,\\r\\n                                    @vchServerName,\\r\\n                                    @vchDatabaseName,\\r\\n                                    @vchLoginName,\\r\\n                                    @vchPassword\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        exec @iReturn = sp_OAGetProperty @iObjectId, N\'GetStreamObject\', @iStreamObjectId OUT\\r\\n\\r\\n        if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n        create table #ObjectList (id int identity, vchObjectlist nvarchar(255))\\r\\n\\r\\n        select @vchTempText = N\'STUB\'\\r\\n        while @vchTempText IS NOT NULL\\r\\n        begin\\r\\n            exec @iReturn = sp_OAMethod @iStreamObjectId, N\'GetStream\', @iReturnValue OUT, @vchTempText OUT\\r\\n            if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n            if (@vchTempText IS NOT NULL) insert into #ObjectList (vchObjectlist ) select @vchTempText\\r\\n        end\\r\\n\\r\\n        select vchObjectlist from #ObjectList order by id\\r\\n    end\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror_u @iObjectId, @iReturn\\r\\n    goto CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_removefromsourcecontrol\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create procedure dbo.dt_removefromsourcecontrol\\r\\n\\r\\nas\\r\\n\\r\\n    set nocount on\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    exec dbo.dt_droppropertiesbyid @iPropertyObjectId, null\\r\\n\\r\\n    \\/* -1 is returned by dt_droppopertiesbyid *\\/\\r\\n    if @@error <> 0 and @@error <> -1 return 1\\r\\n\\r\\n    return 0\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_setpropertybyid\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tIf the property already exists, reset the value; otherwise add property\\r\\n**\\t\\tid -- the id in sysobjects of the object\\r\\n**\\t\\tproperty -- the name of the property\\r\\n**\\t\\tvalue -- the text value of the property\\r\\n**\\t\\tlvalue -- the binary value of the property (image)\\r\\n*\\/\\r\\ncreate procedure dbo.dt_setpropertybyid\\r\\n\\t@id int,\\r\\n\\t@property varchar(64),\\r\\n\\t@value varchar(255),\\r\\n\\t@lvalue image\\r\\nas\\r\\n\\tset nocount on\\r\\n\\tdeclare @uvalue nvarchar(255) \\r\\n\\tset @uvalue = convert(nvarchar(255), @value) \\r\\n\\tif exists (select * from dbo.dtproperties \\r\\n\\t\\t\\twhere objectid=@id and property=@property)\\r\\n\\tbegin\\r\\n\\t\\t--\\r\\n\\t\\t-- bump the version count for this row as we update it\\r\\n\\t\\t--\\r\\n\\t\\tupdate dbo.dtproperties set value=@value, uvalue=@uvalue, lvalue=@lvalue, version=version+1\\r\\n\\t\\t\\twhere objectid=@id and property=@property\\r\\n\\tend\\r\\n\\telse\\r\\n\\tbegin\\r\\n\\t\\t--\\r\\n\\t\\t-- version count is auto-set to 0 on initial insert\\r\\n\\t\\t--\\r\\n\\t\\tinsert dbo.dtproperties (property, objectid, value, uvalue, lvalue)\\r\\n\\t\\t\\tvalues (@property, @id, @value, @uvalue, @lvalue)\\r\\n\\tend\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_setpropertybyid_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tIf the property already exists, reset the value; otherwise add property\\r\\n**\\t\\tid -- the id in sysobjects of the object\\r\\n**\\t\\tproperty -- the name of the property\\r\\n**\\t\\tuvalue -- the text value of the property\\r\\n**\\t\\tlvalue -- the binary value of the property (image)\\r\\n*\\/\\r\\ncreate procedure dbo.dt_setpropertybyid_u\\r\\n\\t@id int,\\r\\n\\t@property varchar(64),\\r\\n\\t@uvalue nvarchar(255),\\r\\n\\t@lvalue image\\r\\nas\\r\\n\\tset nocount on\\r\\n\\t-- \\r\\n\\t-- If we are writing the name property, find the ansi equivalent. \\r\\n\\t-- If there is no lossless translation, generate an ansi name. \\r\\n\\t-- \\r\\n\\tdeclare @avalue varchar(255) \\r\\n\\tset @avalue = null \\r\\n\\tif (@uvalue is not null) \\r\\n\\tbegin \\r\\n\\t\\tif (convert(nvarchar(255), convert(varchar(255), @uvalue)) = @uvalue) \\r\\n\\t\\tbegin \\r\\n\\t\\t\\tset @avalue = convert(varchar(255), @uvalue) \\r\\n\\t\\tend \\r\\n\\t\\telse \\r\\n\\t\\tbegin \\r\\n\\t\\t\\tif \'DtgSchemaNAME\' = @property \\r\\n\\t\\t\\tbegin \\r\\n\\t\\t\\t\\texec dbo.dt_generateansiname @avalue output \\r\\n\\t\\t\\tend \\r\\n\\t\\tend \\r\\n\\tend \\r\\n\\tif exists (select * from dbo.dtproperties \\r\\n\\t\\t\\twhere objectid=@id and property=@property)\\r\\n\\tbegin\\r\\n\\t\\t--\\r\\n\\t\\t-- bump the version count for this row as we update it\\r\\n\\t\\t--\\r\\n\\t\\tupdate dbo.dtproperties set value=@avalue, uvalue=@uvalue, lvalue=@lvalue, version=version+1\\r\\n\\t\\t\\twhere objectid=@id and property=@property\\r\\n\\tend\\r\\n\\telse\\r\\n\\tbegin\\r\\n\\t\\t--\\r\\n\\t\\t-- version count is auto-set to 0 on initial insert\\r\\n\\t\\t--\\r\\n\\t\\tinsert dbo.dtproperties (property, objectid, value, uvalue, lvalue)\\r\\n\\t\\t\\tvalues (@property, @id, @avalue, @uvalue, @lvalue)\\r\\n\\tend\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_validateloginparams\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_validateloginparams\\r\\n    @vchLoginName  varchar(255),\\r\\n    @vchPassword   varchar(255)\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId =0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchSourceSafeINI varchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n\\r\\n    exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                \'ValidateLoginParams\',\\r\\n                                NULL,\\r\\n                                @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                @sLoginName = @vchLoginName,\\r\\n                                @sPassword = @vchPassword\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror @iObjectId, @iReturn\\r\\n    GOTO CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_validateloginparams_u\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_validateloginparams_u\\r\\n    @vchLoginName  nvarchar(255),\\r\\n    @vchPassword   nvarchar(255)\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId =0\\r\\n\\r\\ndeclare @VSSGUID nvarchar(100)\\r\\nselect @VSSGUID = N\'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n    declare @iPropertyObjectId int\\r\\n    select @iPropertyObjectId = (select objectid from dbo.dtproperties where property = \'VCSProjectID\')\\r\\n\\r\\n    declare @vchSourceSafeINI nvarchar(255)\\r\\n    exec dbo.dt_getpropertiesbyid_vcs_u @iPropertyObjectId, \'VCSSourceSafeINI\', @vchSourceSafeINI OUT\\r\\n\\r\\n    exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\n    exec @iReturn = sp_OAMethod @iObjectId,\\r\\n                                N\'ValidateLoginParams\',\\r\\n                                NULL,\\r\\n                                @sSourceSafeINI = @vchSourceSafeINI,\\r\\n                                @sLoginName = @vchLoginName,\\r\\n                                @sPassword = @vchPassword\\r\\n    if @iReturn <> 0 GOTO E_OAError\\r\\n\\r\\nCleanUp:\\r\\n    return\\r\\n\\r\\nE_OAError:\\r\\n    exec dbo.dt_displayoaerror_u @iObjectId, @iReturn\\r\\n    GOTO CleanUp\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_vcsenabled\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_vcsenabled\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iObjectId int\\r\\nselect @iObjectId = 0\\r\\n\\r\\ndeclare @VSSGUID varchar(100)\\r\\nselect @VSSGUID = \'SQLVersionControl.VCS_SQL\'\\r\\n\\r\\n    declare @iReturn int\\r\\n    exec @iReturn = sp_OACreate @VSSGUID, @iObjectId OUT\\r\\n    if @iReturn <> 0 raiserror(\'\', 16, -1) \\/* Can\'t Load Helper DLLC *\\/\\r\\n\\r\\n\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_verstamp006\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"\\/*\\r\\n**\\tThis procedure returns the version number of the stored\\r\\n**    procedures used by the Microsoft Visual Database Tools.\\r\\n**    Current version is 7.0.00.\\r\\n*\\/\\r\\ncreate procedure dbo.dt_verstamp006\\r\\nas\\r\\n\\tselect 7000\\r\\n\"},{\"schema_name\":\"dbo\",\"name\":\"dt_whocheckedout\",\"type_desc\":\"SQL_STORED_PROCEDURE\",\"definition\":\"create proc dbo.dt_whocheckedout\\r\\n        @chObjectType  char(4),\\r\\n        @vchObjectName varchar(255),\\r\\n        @vchLoginName  varchar(255),\\r\\n        @vchPassword   varchar(255)\\r\\n\\r\\nas\\r\\n\\r\\nset nocount on\\r\\n\\r\\ndeclare @iReturn int\\r\\ndeclare @iObjectId int\\r\\nselect @iOb